                    foreach ($p in $combo.PSObject.Properties) { $clone[$p.Name] = $p.Value }
                    foreach ($p in $ruleProps) { $clone[$p.Name] = $p.Value }
                    $result[$i] = [pscustomobject]$clone
                }
            }
        }

        if (-not $matchedAny) {
            $clone = [ordered]@{}
            foreach ($p in $ruleProps) { $clone[$p.Name] = $p.Value }
            $result.Add([pscustomobject]$clone)
        }
    }

    return , @($result.ToArray())
}

